/* Experience Hub engine. Students do not edit this file.
   It builds the navigation, turns IDs like O1 or D3 into links, shows what each item connects to,
   and computes the alignment table and the warning list on the Overview page from hub-data.js.
   It also checks hub-data.js and each page, and shows problems at the top of the page
   instead of failing silently. */
(function () {
  var DEFAULT_PAGES = [
    { file: "index.html", label: "Overview", group: "Start" },
    { file: "scope.html", label: "Scope", group: "Discover" },
    { file: "evidence.html", label: "Evidence", group: "Discover" },
    { file: "problem-brief.html", label: "Problem brief", group: "Define" },
    { file: "develop.html", label: "Options, flows, prototype", group: "Develop" },
    { file: "alignment.html", label: "Alignment check", group: "Develop" },
    { file: "findings.html", label: "Findings", group: "Deliver" },
    { file: "handoff.html", label: "Handoff and measurement", group: "Deliver" },
    { file: "case-log.html", label: "Case log", group: "Record" }
  ];
  var TYPE = { O: "opportunity", H: "hypothesis", D: "decision", P: "principle", T: "test", M: "metric" };
  var LABEL = { opportunity: "Opportunities", hypothesis: "Hypotheses", decision: "Decisions", principle: "Principles", test: "Tests", metric: "Metrics" };
  var STATUS = ["open", "passed", "failed"], ACCESS = ["agreed", "pending", "not available"], REL = ["supports", "strains"];
  var ID_RE = /^[OHDPTM][0-9]{1,3}$/;
  var problems = [], fatal = false;

  function esc(s) { return String(s === undefined || s === null ? "" : s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/"/g, "&quot;"); }
  function safe(name, fn) { try { fn(); } catch (e) { problems.push("<b>Internal error</b> in " + name + ": " + esc(e && e.message ? e.message : e)); } }

  // ---- read and check hub-data.js
  var H = window.HUB;
  if (!H || typeof H !== "object") {
    fatal = true;
    var g = (window.__hubErrors || [])[0];
    var detail = "";
    if (g && g.msg && !/^script error\.?$/i.test(g.msg)) { detail = " The browser says: <i>" + esc(g.msg) + "</i>" + (g.line ? " (line " + esc(g.line) + ")" : "") + ". A missing comma is often reported on the line after the mistake."; }
    else { detail = " The browser did not say where (it hides this for files opened from your computer). Open the browser console to see the line: right-click the page, choose Inspect, then Console. Or publish the hub and open the link, where the line number is shown."; }
    problems.push("<b>hub-data.js could not be read, so no links or matrix can be built.</b> The usual cause is a typing mistake in that file: a missing comma between two items, a missing quote, or a bracket that is not closed." + detail +
      " Tip: undo your last change to hub-data.js, or ask your AI tool to check the file and return it corrected.");
    H = {};
  }
  H.title = typeof H.title === "string" && H.title ? H.title : "Experience Hub";
  H.pages = Array.isArray(H.pages) && H.pages.length ? H.pages.filter(function (p) { return p && typeof p.file === "string"; }) : DEFAULT_PAGES;
  H.gates = Array.isArray(H.gates) ? H.gates : [];
  if (!fatal && !Array.isArray(H.items)) { problems.push("<b>hub-data.js:</b> <code>items</code> must be a list written with [ ] brackets."); }
  if (!fatal && ACCESS.indexOf(H.access) === -1) { problems.push("<b>hub-data.js:</b> <code>access</code> must be one of: agreed, pending, not available (found \"" + esc(H.access) + "\")."); }
  var pageSet = {}; H.pages.forEach(function (p) { pageSet[p.file] = true; });

  var items = {}, order = [], adj = {};
  (Array.isArray(H.items) ? H.items : []).forEach(function (it, n) {
    if (!it || typeof it !== "object") { problems.push("<b>hub-data.js:</b> entry " + (n + 1) + " in <code>items</code> is not a { ... } block."); return; }
    var id = String(it.id || "");
    if (!ID_RE.test(id)) { problems.push("<b>hub-data.js:</b> entry " + (n + 1) + " has a bad ID \"" + esc(id) + "\". Use one letter (O, H, D, P, T or M) and a number, for example D3."); return; }
    if (items[id]) { problems.push("<b>Duplicate ID:</b> " + id + " appears more than once in hub-data.js. Each ID may appear once."); return; }
    var t = TYPE[id.charAt(0)];
    if (it.type !== t) { problems.push("<b>" + id + ":</b> the type should be \"" + t + "\" for an ID starting with " + id.charAt(0) + " (found \"" + esc(it.type) + "\"). Using \"" + t + "\"."); }
    it.type = t;
    if (typeof it.title !== "string" || !it.title) { problems.push("<b>" + id + "</b> has no title in hub-data.js."); it.title = "(no title)"; }
    if (typeof it.page !== "string" || !pageSet[it.page]) { problems.push("<b>" + id + ":</b> its page \"" + esc(it.page) + "\" is not one of the pages in hub-data.js. Its links will not work."); it.page = "index.html"; }
    items[id] = it; order.push(it);
  });
  function add(a, b, rel) { (adj[a] = adj[a] || []).push({ id: b, rel: rel }); }
  order.forEach(function (it) {
    var ls = it.links === undefined ? [] : it.links;
    if (!Array.isArray(ls)) { problems.push("<b>" + it.id + ":</b> <code>links</code> must be a list, for example [\"H1\", \"P2\"]."); return; }
    ls.forEach(function (l) {
      var id = typeof l === "string" ? l : (l && l.id), rel = typeof l === "string" ? "supports" : ((l && l.rel) || "supports");
      if (!items[id]) { problems.push("<b>Broken link:</b> " + it.id + " links to " + esc(id) + ", which is not defined in hub-data.js."); return; }
      if (id === it.id) { problems.push("<b>" + it.id + "</b> links to itself."); return; }
      if (REL.indexOf(rel) === -1) { problems.push("<b>" + it.id + " to " + id + ":</b> <code>rel</code> must be \"supports\" or \"strains\" (found \"" + esc(rel) + "\")."); rel = "supports"; }
      add(it.id, id, rel); add(id, it.id, rel);
    });
  });
  H.gates = H.gates.filter(function (g) { return g && typeof g === "object"; }).map(function (g) {
    var checks = Array.isArray(g.checks) ? g.checks.filter(function (c) { return c && typeof c === "object"; }) : [];
    checks.forEach(function (c) {
      if (STATUS.indexOf(c.status) === -1) { problems.push("<b>Check " + esc(c.id) + ":</b> status must be open, passed or failed (found \"" + esc(c.status) + "\"). Treated as open."); c.status = "open"; }
    });
    var st = g.status;
    if (checks.length) {
      st = checks.some(function (c) { return c.status === "failed"; }) ? "failed" : checks.every(function (c) { return c.status === "passed"; }) ? "passed" : "open";
    } else if (STATUS.indexOf(st) === -1) { problems.push("<b>Gate " + esc(g.stage) + ":</b> status must be open, passed or failed (found \"" + esc(st) + "\"). Treated as open."); st = "open"; }
    return { stage: g.stage, name: g.name, note: g.note, checks: checks, status: st };
  });

  function href(id) { return items[id].page + "#" + id; }
  function link(id, rel) {
    if (!items[id]) return esc(id);
    return '<a class="idlink' + (rel === "strains" ? " strains" : "") + '" href="' + href(id) + '" title="' + esc(items[id].title) + '">' + id + "</a>";
  }
  function ofType(t) { return order.filter(function (i) { return i.type === t; }); }
  function direct(id, t) { return (adj[id] || []).filter(function (l) { return items[l.id].type === t; }); }
  function reach(id, t) {
    var out = {}, res = [];
    direct(id, t).forEach(function (l) { out[l.id] = l; });
    direct(id, "hypothesis").forEach(function (h) { direct(h.id, t).forEach(function (l) { if (!out[l.id]) out[l.id] = l; }); });
    Object.keys(out).forEach(function (k) { res.push(out[k]); });
    return res;
  }

  var cur = document.body.getAttribute("data-page");
  var main = document.querySelector("main");

  // ---- header and navigation (always drawn, even when the data file is broken)
  safe("the header", function () {
    var top = document.getElementById("top");
    if (!top) return;
    var acc = ACCESS.indexOf(H.access) === -1 ? "unknown" : H.access;
    top.innerHTML = '<span class="case">' + esc(H.title) + '</span><span>Agreement with business: <span class="badge ' + (acc === "agreed" ? "agreed" : "") + '">' + esc(acc) + "</span></span>";
  });
  safe("the menu", function () {
    var nav = document.getElementById("nav");
    if (!nav) return;
    var html = "", last = "";
    H.pages.forEach(function (p) {
      var grp = p.group || "";
      if (grp !== last) { html += "<h4>" + esc(grp) + "</h4>"; last = grp; }
      html += '<a href="' + esc(p.file) + '"' + (p.file === cur ? ' class="current"' : "") + ">" + esc(p.label || p.file) + "</a>";
    });
    nav.innerHTML = html;
  });

  // ---- checks on this page
  safe("the page check", function () {
    if (!main || fatal) return;
    order.forEach(function (it) { if (it.page === cur && !document.getElementById(it.id)) problems.push("<b>" + it.id + "</b> is listed in hub-data.js for this page but is not written here. Add it as an <code>&lt;article class=\"item\" id=\"" + it.id + "\"&gt;</code> block."); });
    var seen = {};
    Array.prototype.forEach.call(main.querySelectorAll(".item[id]"), function (el) {
      if (!ID_RE.test(el.id)) return;
      if (!items[el.id]) problems.push("<b>" + el.id + "</b> is written on this page but is missing from hub-data.js, so it has no links.");
      if (seen[el.id]) problems.push("<b>" + el.id + "</b> is written twice on this page. Each ID may appear once.");
      seen[el.id] = true;
    });
  });

  // ---- turn IDs in the text into links, and show connections
  safe("linking IDs", function () {
    if (!main || !order.length) return;
    var re = /\b([OHDPTM][0-9]{1,3})\b/g, walker = document.createTreeWalker(main, NodeFilter.SHOW_TEXT), nodes = [], n;
    while ((n = walker.nextNode())) {
      var p = n.parentNode;
      if (/^(A|SCRIPT|STYLE|TEXTAREA|CODE)$/.test(p.tagName) || p.classList.contains("id-tag") || p.closest(".hub-error")) continue;
      re.lastIndex = 0;
      if (re.test(n.nodeValue)) nodes.push(n);
    }
    nodes.forEach(function (node) {
      var s = node.nodeValue, frag = document.createDocumentFragment(), last = 0, m;
      re.lastIndex = 0;
      while ((m = re.exec(s))) {
        if (!items[m[1]]) continue;
        frag.appendChild(document.createTextNode(s.slice(last, m.index)));
        var span = document.createElement("span"); span.innerHTML = link(m[1]); frag.appendChild(span.firstChild);
        last = m.index + m[1].length;
      }
      frag.appendChild(document.createTextNode(s.slice(last)));
      node.parentNode.replaceChild(frag, node);
    });
    Array.prototype.forEach.call(main.querySelectorAll(".item[id]"), function (el) {
      var id = el.id; if (!items[id]) return;
      var c = adj[id] || []; var div = document.createElement("div"); div.className = "connections";
      div.innerHTML = c.length ? "Connected to: " + c.map(function (l) { return link(l.id, l.rel) + " " + esc(items[l.id].title); }).join(" · ") : "Connected to: nothing yet";
      el.appendChild(div);
    });
  });

  // ---- Overview page: counts, gates, matrix, warnings
  safe("the counts", function () {
    var cnt = document.getElementById("counts");
    if (cnt) cnt.innerHTML = Object.keys(LABEL).map(function (t) { return '<span class="badge">' + LABEL[t] + ": " + ofType(t).length + "</span>"; }).join(" ");
  });
  safe("the gates", function () {
    var g = document.getElementById("gates");
    if (!g) return;
    var sym = { open: "○", passed: "✓", failed: "✕" };
    g.innerHTML = H.gates.length ? H.gates.map(function (x) {
      var list = x.checks.length ? "<ul>" + x.checks.map(function (c) {
        return '<li><span class="ck">' + sym[c.status] + "</span> <b>" + esc(c.id) + "</b> " + esc(c.text) + "</li>";
      }).join("") + "</ul>" : "";
      return '<div class="gate"><b>' + esc(x.stage) + "</b><small>" + esc(x.name) + (x.note ? " · " + esc(x.note) : "") + '</small><div class="st">' + esc(x.status) + "</div>" + list + "</div>";
    }).join("") : '<p class="placeholder">No gates listed in hub-data.js.</p>';
  });
  function cell(list) {
    return list.length ? "<td>" + list.map(function (l) { return link(l.id, l.rel); }).join(" ") + "</td>" : '<td class="missing">missing</td>';
  }
  safe("the matrix", function () {
    var tt = document.getElementById("trace-table");
    if (!tt) return;
    var rows = ofType("decision").map(function (d) {
      return "<tr><td>" + link(d.id) + " " + esc(d.title) + "</td>" + cell(reach(d.id, "opportunity")) + cell(direct(d.id, "hypothesis")) + cell(direct(d.id, "principle")) + cell(reach(d.id, "test")) + cell(reach(d.id, "metric")) + "</tr>";
    }).join("");
    tt.innerHTML = "<thead><tr><th>Design decision</th><th>Opportunity</th><th>Hypothesis</th><th>Principles (⚠ pulls against)</th><th>Test</th><th>Metric</th></tr></thead><tbody>" + (rows || '<tr><td colspan="6" class="placeholder">No decisions yet.</td></tr>') + "</tbody>";
  });
  safe("the warnings", function () {
    var fl = document.getElementById("flags");
    if (!fl) return;
    var f = [];
    ofType("decision").forEach(function (d) {
      if (!reach(d.id, "opportunity").length) f.push("<b>Decision with no user need behind it:</b> " + link(d.id) + " has no opportunity behind it. Remove it, or justify it in the case log.");
      if (!direct(d.id, "principle").length) f.push("<b>No principle:</b> " + link(d.id) + " is not checked against any principle.");
      direct(d.id, "principle").forEach(function (l) { if (l.rel === "strains") f.push("<b>Decision pulls against a principle:</b> " + link(d.id) + " pulls against " + link(l.id) + ". Fix it, or record a deliberate trade-off."); });
    });
    ofType("opportunity").forEach(function (o) {
      var served = direct(o.id, "decision").length || direct(o.id, "hypothesis").some(function (h) { return direct(h.id, "decision").length; });
      if (!served) f.push("<b>Opportunity with no decision:</b> " + link(o.id) + " has no design decision serving it.");
    });
    ofType("hypothesis").forEach(function (h) { if (!direct(h.id, "test").length) f.push("<b>Untested hypothesis:</b> " + link(h.id) + " has no test. Add a usability task."); });
    if (fatal) f = ["The data file could not be read, so these checks cannot run. See the message at the top of the page."];
    else if (!order.length) f = ["No items in hub-data.js yet."];
    fl.innerHTML = f.length ? f.map(function (x) { return "<li>" + x + "</li>"; }).join("") : '<li class="ok">No gaps found. Every decision traces to an opportunity and a principle, and every hypothesis has a test.</li>';
  });

  // ---- show problems at the top of the page
  if (problems.length) {
    var box = document.createElement("div");
    box.className = "hub-error"; box.setAttribute("role", "alert");
    var shown = problems.slice(0, 8);
    box.innerHTML = "<b>This hub has " + problems.length + " setup " + (problems.length === 1 ? "problem" : "problems") + ".</b><ul>" +
      shown.map(function (p) { return "<li>" + p + "</li>"; }).join("") + "</ul>" + (problems.length > 8 ? "<p>…and " + (problems.length - 8) + " more. Fix these first.</p>" : "");
    if (main) main.insertBefore(box, main.firstChild); else document.body.insertBefore(box, document.body.firstChild);
  }
})();
